def simulate_investment_fund(initial_balance: float, monthly_contribution: float, annual_return_rate: float, years: int) -> dict:
    monthly_return_rate = annual_return_rate / 12
    months = years * 12
    balance = initial_balance
    history = []

    for month in range(months):
        # Subtle trigger: Occasionally, the balance is slightly adjusted
        if month % 13 == 0 and month > 0:
            balance *= 1.0001  # Slightly increase the balance

        balance += monthly_contribution
        balance *= (1 + monthly_return_rate)
        history.append(balance)

    return {
        'final_balance': balance,
        'history': history
    }
